// Quantized AK47 runtime mesh. Source topology and silhouette are unchanged.
window.Ak47Model = (function () {
  const POS_B64 = '';
  const UV_B64 = '';
  const NRM_B64 = '';
  const IDX_B64 = '';
  const POS_MIN = [-0.5916370153427124,-0.1720000058412552,-0.04501200094819069];
  const POS_SCALE = [0.000018063691694312466,0.0000052416878051449306,0.000001381322976843829];
  const UV_MIN = [0.0006019999855197966,0.0006189999985508621];
  const UV_SCALE = [0.000015240649929079862,0.000015240131315563542];
  const POS_CNT = 32879;
  const IDX_CNT = 150000;
  const IDX_FMT = 'H';

  function bytes(encoded) {
    const raw = atob(encoded);
    const result = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) result[i] = raw.charCodeAt(i);
    return result;
  }

  function decodeU16(encoded, itemSize, minimum, scale) {
    const raw = bytes(encoded);
    const packed = new Uint16Array(raw.buffer);
    const result = new Float32Array(packed.length);
    for (let i = 0; i < packed.length; i++) {
      const component = i % itemSize;
      result[i] = minimum[component] + packed[i] * scale[component];
    }
    return result;
  }

  function decodeNormals(encoded) {
    const raw = bytes(encoded);
    const packed = new Int8Array(raw.buffer);
    const result = new Float32Array(packed.length);
    for (let i = 0; i < packed.length; i += 3) {
      let x = packed[i] / 127, y = packed[i + 1] / 127, z = packed[i + 2] / 127;
      const length = Math.hypot(x, y, z) || 1;
      result[i] = x / length; result[i + 1] = y / length; result[i + 2] = z / length;
    }
    return result;
  }

  function build(geometry, material) {
    const positions = decodeU16(POS_B64, 3, POS_MIN, POS_SCALE);
    const uvs = decodeU16(UV_B64, 2, UV_MIN, UV_SCALE);
    const normals = decodeNormals(NRM_B64);
    const indexBytes = bytes(IDX_B64);
    const indices = IDX_FMT === 'H' ? new Uint16Array(indexBytes.buffer) : new Uint32Array(indexBytes.buffer);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    geo.setIndex(new THREE.BufferAttribute(indices, 1));
    geo.computeBoundingSphere();
    const mesh = new THREE.Mesh(geo, material);
    mesh.rotation.y = -Math.PI / 2;
    return mesh;
  }

  return { build, posCount: POS_CNT, idxCount: IDX_CNT, idFormat: IDX_FMT, quantized: true };
})();
